"""Record final built-in ImageGen prompts and hashes beside project assets."""
from pathlib import Path
import hashlib,json
ROOT=Path(__file__).resolve().parents[1]
COMMON='Use case: stylized-concept. ONE finished 16:9 cinematic full-screen hero background for Leo Racer. Polished realistic AAA racing-title key art, grounded natural landmark proportions, beautiful physically plausible surfaces and atmospheric lighting, restrained navy/cyan/warm-gold harmony with lush natural colors. Keep lower-left45% quiet and somewhat darker for readable live controls. No people, cars, UI, text, letters, logos, watermarks or borders. Finished landscape artwork.'
PROMPTS={
'galle':'Use case: stylized-concept. Create ONE finished 16:9 landscape full-screen hero background for Leo Racer, cinematic polished realistic game key art. Sri Lanka GALLE FORT: recognizable Dutch fort sea ramparts and Galle lighthouse, Indian Ocean, wind-shaped palms and warm old masonry, blue-hour twilight with subtle amber lamps, grounded natural proportions. Elegant AAA racing-title visual direction, restrained navy/cyan/warm-gold palette, physically plausible surfaces, beautiful soft lighting, detailed but calm composition. No racing track implied through heritage site. Keep lower-left 45% relatively quiet and darker for live controls; landmark on upper-right with generous sky. No cars, people, UI, words, letters, logos, watermarks, borders. Produce actual finished artwork, wide 16:9.',
'hikkaduwa':COMMON+' Sri Lanka HIKKADUWA coast: inviting palm-lined tropical beach bay, turquoise Indian Ocean and gentle surf, low terracotta-roof coastal guesthouses, distant fishing boats, late sunset blue hour, soft warm lamps, ocean foreground sweeping toward village right. No invented giant landmarks.',
'nine_arch':COMMON+' Sri Lanka NINE ARCH BRIDGE at Ella: historically recognizable long curved nine-arch stone railway viaduct with all nine arches visibly plausible, lush tea hills and rainforest, early mist and warm sunrise rays, view from lush hillside showing elegant bridge across valley. Railway bridge only, no road or racing on it. Bridge occupies right two-thirds, soft mist valley lower left.',
'sigiriya':COMMON+' Sri Lanka SIGIRIYA: iconic isolated massive Lion Rock with sheer reddish stone sides and green summit ruins above lush dry-zone forest, ancient water gardens and reflecting pools foreground, golden late-afternoon light through humid haze. Authentic recognizable rock shape, no invented castles or high buildings on summit. Rock upper-right with graceful reflection; water garden lower-left quiet.',
'dalada':COMMON+' Sri Lanka SRI DALADA MALIGAWA, Temple of the Tooth in Kandy: recognizable white temple facade, golden roof and octagonal Pattirippuwa beside Kandy Lake, cloudy hill-country blue hour with subtle amber illumination, calm reflected architecture, respectful serene setting, no festival crowds or religious figures. Temple right half, lake and quiet sky on left.',
'sri_lanka_surfaces':'Generate ONE game-ready 2x2 MATERIAL TEXTURE ATLAS, square, exactly four equally-sized square panels filling frame with no borders, labels, gaps, text or objects. Each panel a straight-on orthographic macro surface texture, uniform neutral diffuse illumination, no baked shadows, no perspective. Top-left warm aged Sri Lankan lime plaster with subtle weathering; top-right terracotta clay tile surface with sparse grain; bottom-left richly woven teal/ochre handwoven awning cloth pattern; bottom-right weathered warm gray stone masonry. Realistic PBR basecolor quality, believable scale, restrained natural tones, seamless boundaries within each independent tile, no logos. This is a flat material texture atlas, not a scene.'}
def main():
    rows=[]
    for name,prompt in PROMPTS.items():
        path=ROOT/('assets/art/scenery279/sri_lanka_surfaces.png' if name=='sri_lanka_surfaces' else 'assets/ui/boot/gallery279/'+name+'.png')
        rows.append({'file':path.relative_to(ROOT).as_posix(),'tool':'built-in image_gen.imagegen','transparent_background':False,'prompt':prompt,'sha256':hashlib.sha256(path.read_bytes()).hexdigest()})
    (ROOT/'assets/config/generated-art-v279.json').write_text(json.dumps({'version':'2.7.9','type':'Generated artwork, not gameplay photography','files':rows},indent=2)+'\n',encoding='utf-8')
    (ROOT/'licenses/ARTWORK_279.md').write_text('# Leo Racer 2.7.9 artwork\n\nFive new Sri Lankan location heroes and one four-panel scenery material atlas were created with built-in ImageGen. Final prompts, destination paths and SHA-256 hashes are in assets/config/generated-art-v279.json (also supplied with release provenance). Loading artwork is illustrative key art, not a representation of playable tracks. Existing and older artwork is preserved and credited by its original manifests; loading-gallery-v279.json inventories every selected full-screen original. Portrait promotional posters, UI icons and car thumbnails are not full-screen backgrounds.\n',encoding='utf-8')
    print('ART_PROVENANCE',len(rows))
if __name__=='__main__':main()
